<?php
require __DIR__.'/config.php';$q=trim($_GET['q']??'');$sort=$_GET['sort']??'recent';$order=match($sort){'views'=>'v.views DESC','random'=>'RANDOM()',default=>'v.created_at DESC'};
$sql='SELECT v.*,u.username FROM videos v JOIN users u ON u.id=v.user_id';$args=[];if($q!==''){$sql.=' WHERE v.title LIKE ? OR v.description LIKE ? OR u.username LIKE ?';$like='%'.$q.'%';$args=[$like,$like,$like];}$sql.=" ORDER BY $order LIMIT 100";$st=db()->prepare($sql);$st->execute($args);$videos=$st->fetchAll();require __DIR__.'/includes/header.php';?>
<div class="listing"><div class="listing-nav"><a href="videos.php?sort=recent">Most Recent</a> | <a href="videos.php?sort=views">Most Viewed</a> | <a href="videos.php?sort=random">Random</a></div><h2>Browse Videos</h2><div class="video-grid"><?php foreach($videos as $v):?><div class="video-cell"><a href="watch.php?id=<?=$v['id']?>"><img class="video-thumb" src="<?=h(video_thumb($v))?>" alt=""></a><a href="watch.php?id=<?=$v['id']?>"><?=h($v['title'])?></a><br>By: <a href="profile.php?id=<?=$v['user_id']?>"><?=h($v['username'])?></a><br><span class="red">Views: <?=number_format($v['views'])?></span></div><?php endforeach;?><?php if(!$videos):?><p class="empty">No videos found.</p><?php endif;?></div></div>
<?php require __DIR__.'/includes/footer.php';?>
